-- Actual manual custody/location observations; no inventory allocation or movements.
CREATE TABLE inventory_custody_roots(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>0),custody_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,custody_number));
CREATE TABLE inventory_custody_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES inventory_custody_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),receipt_version_id TEXT NOT NULL REFERENCES purchase_receipt_versions(id),receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0),stock_sequence INTEGER NOT NULL CHECK(stock_sequence>0),outbound_revision INTEGER NOT NULL CHECK(outbound_revision>=0),product_return_revision INTEGER NOT NULL CHECK(product_return_revision>=0),observed_at TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),bucket TEXT NOT NULL CHECK(bucket IN('available','quarantined')),identity_source TEXT NOT NULL,location_label TEXT NOT NULL,location_source TEXT NOT NULL,source_reference TEXT NOT NULL,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version));
CREATE TABLE inventory_custody_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES inventory_custody_roots(id),version_id TEXT NOT NULL REFERENCES inventory_custody_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('observe','withdraw')),status TEXT NOT NULL CHECK(status IN('recorded','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence));
CREATE VIEW inventory_custody_current AS SELECT * FROM inventory_custody_events e WHERE revision=(SELECT max(revision) FROM inventory_custody_events WHERE root_id=e.root_id);
CREATE TRIGGER inventory_custody_root_source BEFORE INSERT ON inventory_custody_roots BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM purchase_receipts r JOIN purchase_receipt_current c ON c.receipt_id=r.id WHERE r.id=NEW.receipt_id AND r.store_id=NEW.store_id AND c.status='posted' AND r.bound_quantity>0) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM inventory_custody_roots WHERE store_id=NEW.store_id),1) OR NEW.custody_number IS NOT 'CUS-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'custody original posted receipt/root') END;
END;
CREATE TRIGGER inventory_custody_version_source BEFORE INSERT ON inventory_custody_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_custody_roots c JOIN purchase_receipts r ON r.id=c.receipt_id JOIN purchase_receipt_current e ON e.receipt_id=r.id JOIN inventory_balances b ON b.product_id=r.product_id JOIN inventory_events s ON s.id=(SELECT id FROM inventory_events WHERE product_id=r.product_id ORDER BY sequence DESC LIMIT 1) WHERE c.id=NEW.root_id AND c.store_id=NEW.store_id AND e.status='posted' AND e.version_id=NEW.receipt_version_id AND NEW.stock_sequence=s.sequence AND NEW.quantity<=CASE NEW.bucket WHEN 'available' THEN b.available ELSE b.quarantined END AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0) AND NEW.observed_at>=(SELECT max(created_at) FROM purchase_receipt_events WHERE receipt_id=r.id AND action='inbound') AND NEW.outbound_revision=coalesce((SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=r.product_id),0) AND NEW.product_return_revision=coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=r.product_id),0)) OR NEW.version<>coalesce((SELECT max(version)+1 FROM inventory_custody_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR length(NEW.observed_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.observed_at) IS NOT NEW.observed_at OR NEW.observed_at>NEW.created_at THEN RAISE(ABORT,'custody actual source/current capacity/time') END;
END;
CREATE TRIGGER inventory_custody_event_source BEFORE INSERT ON inventory_custody_events BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_custody_roots r JOIN inventory_custody_versions v ON v.root_id=r.id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND v.id=NEW.version_id) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM inventory_custody_events WHERE root_id=NEW.root_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM inventory_custody_events WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT(NEW.action='observe' AND NEW.status='recorded' AND EXISTS(SELECT 1 FROM inventory_custody_versions v WHERE v.id=NEW.version_id AND v.version=(SELECT coalesce(max(version),0)+1 FROM inventory_custody_versions WHERE root_id=NEW.root_id AND id<>v.id) AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR NEW.action='withdraw' AND NEW.status='withdrawn' AND EXISTS(SELECT 1 FROM inventory_custody_current c WHERE c.root_id=NEW.root_id AND c.status='recorded' AND c.version_id=NEW.version_id)) THEN RAISE(ABORT,'custody explicit paired observation/withdrawal') END;
END;
CREATE TABLE inventory_custody_stock_context(stock_event_id TEXT PRIMARY KEY REFERENCES inventory_events(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_custody_stock_context SELECT id,0 FROM inventory_events;
CREATE TRIGGER inventory_custody_stock_context_capture AFTER INSERT ON inventory_events BEGIN INSERT INTO inventory_custody_stock_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_stock_context_source BEFORE INSERT ON inventory_custody_stock_context WHEN NOT EXISTS(SELECT 1 FROM inventory_events e WHERE e.id=NEW.stock_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'custody original context');END;
CREATE TRIGGER inventory_custody_stock_context_chronology BEFORE INSERT ON inventory_events WHEN EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original chronology');END;
CREATE TABLE inventory_custody_dispatch_context(outbound_id TEXT PRIMARY KEY REFERENCES inventory_outbounds(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_custody_dispatch_context SELECT id,0 FROM inventory_outbounds;
CREATE TRIGGER inventory_custody_dispatch_context_capture AFTER INSERT ON inventory_outbounds BEGIN INSERT INTO inventory_custody_dispatch_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_dispatch_context_source BEFORE INSERT ON inventory_custody_dispatch_context WHEN NOT EXISTS(SELECT 1 FROM inventory_outbounds e WHERE e.id=NEW.outbound_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'custody original context');END;
CREATE TRIGGER inventory_custody_dispatch_context_chronology BEFORE INSERT ON inventory_outbounds WHEN EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original chronology');END;
CREATE TABLE inventory_custody_receipt_context(receipt_event_id TEXT PRIMARY KEY REFERENCES purchase_receipt_events(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_custody_receipt_context SELECT id,0 FROM purchase_receipt_events;
CREATE TRIGGER inventory_custody_receipt_context_capture AFTER INSERT ON purchase_receipt_events BEGIN INSERT INTO inventory_custody_receipt_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_receipt_context_source BEFORE INSERT ON inventory_custody_receipt_context WHEN NOT EXISTS(SELECT 1 FROM purchase_receipt_events e WHERE e.id=NEW.receipt_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'custody original context');END;
CREATE TRIGGER inventory_custody_receipt_context_chronology BEFORE INSERT ON purchase_receipt_events WHEN EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original chronology');END;
CREATE TABLE inventory_custody_return_context(handoff_id TEXT PRIMARY KEY REFERENCES supplier_return_handoffs(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_custody_return_context SELECT id,0 FROM supplier_return_handoffs;
CREATE TRIGGER inventory_custody_return_context_capture AFTER INSERT ON supplier_return_handoffs BEGIN INSERT INTO inventory_custody_return_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_return_context_source BEFORE INSERT ON inventory_custody_return_context WHEN NOT EXISTS(SELECT 1 FROM supplier_return_handoffs e WHERE e.id=NEW.handoff_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'custody original context');END;
CREATE TRIGGER inventory_custody_return_context_chronology BEFORE INSERT ON supplier_return_handoffs WHEN EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original chronology');END;
CREATE TRIGGER inventory_custody_roots_actor BEFORE INSERT ON inventory_custody_roots WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_custody_versions_actor BEFORE INSERT ON inventory_custody_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_custody_versions_text BEFORE INSERT ON inventory_custody_versions WHEN length(trim(NEW.identity_source)) NOT BETWEEN 1 AND 2000 OR length(NEW.identity_source)>2000 OR length(trim(NEW.location_label)) NOT BETWEEN 1 AND 300 OR length(NEW.location_label)>300 OR length(trim(NEW.location_source)) NOT BETWEEN 1 AND 2000 OR length(NEW.location_source)>2000 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'custody actual source text');END;
CREATE TRIGGER inventory_custody_events_actor BEFORE INSERT ON inventory_custody_events WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_custody_events_text BEFORE INSERT ON inventory_custody_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 BEGIN SELECT RAISE(ABORT,'custody actual source text');END;
CREATE TRIGGER inventory_custody_roots_no_update BEFORE UPDATE ON inventory_custody_roots BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_roots_no_delete BEFORE DELETE ON inventory_custody_roots BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_versions_no_update BEFORE UPDATE ON inventory_custody_versions BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_versions_no_delete BEFORE DELETE ON inventory_custody_versions BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_events_no_update BEFORE UPDATE ON inventory_custody_events BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_events_no_delete BEFORE DELETE ON inventory_custody_events BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_stock_context_no_update BEFORE UPDATE ON inventory_custody_stock_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_stock_context_no_delete BEFORE DELETE ON inventory_custody_stock_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_dispatch_context_no_update BEFORE UPDATE ON inventory_custody_dispatch_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_dispatch_context_no_delete BEFORE DELETE ON inventory_custody_dispatch_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_receipt_context_no_update BEFORE UPDATE ON inventory_custody_receipt_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_receipt_context_no_delete BEFORE DELETE ON inventory_custody_receipt_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_return_context_no_update BEFORE UPDATE ON inventory_custody_return_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_return_context_no_delete BEFORE DELETE ON inventory_custody_return_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_version_time BEFORE INSERT ON inventory_custody_versions BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_custody_roots r JOIN purchase_receipts p ON p.id=r.receipt_id WHERE r.id=NEW.root_id AND (EXISTS(SELECT 1 FROM inventory_events WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_outbounds WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at))) OR EXISTS(SELECT 1 FROM inventory_custody_versions WHERE root_id=NEW.root_id AND observed_at>NEW.observed_at) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM inventory_custody_roots WHERE id=NEW.root_id AND created_at=NEW.created_at AND created_by=NEW.created_by) THEN RAISE(ABORT,'custody adopted source chronology/root pairing') END;
END;
CREATE TRIGGER inventory_custody_source_chronology BEFORE INSERT ON inventory_custody_events WHEN EXISTS(SELECT 1 FROM inventory_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_outbounds WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody whole source chronology');END;
ALTER TABLE inventory_custody_versions ADD COLUMN quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0);
CREATE TABLE inventory_custody_quality_context(quality_event_id TEXT PRIMARY KEY REFERENCES purchase_quality_events(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_custody_quality_context SELECT id,0 FROM purchase_quality_events;
CREATE TRIGGER inventory_custody_quality_context_capture AFTER INSERT ON purchase_quality_events BEGIN INSERT INTO inventory_custody_quality_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_quality_context_source BEFORE INSERT ON inventory_custody_quality_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events e WHERE e.id=NEW.quality_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_custody_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'custody original quality context');END;
CREATE TRIGGER inventory_custody_quality_context_chronology BEFORE INSERT ON purchase_quality_events WHEN EXISTS(SELECT 1 FROM inventory_custody_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original quality chronology');END;
CREATE TRIGGER inventory_custody_quality_context_no_update BEFORE UPDATE ON inventory_custody_quality_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_quality_context_no_delete BEFORE DELETE ON inventory_custody_quality_context BEGIN SELECT RAISE(ABORT,'custody immutable');END;
CREATE TRIGGER inventory_custody_quality_source BEFORE INSERT ON inventory_custody_versions WHEN NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR NEW.bucket='available' AND NOT EXISTS(SELECT 1 FROM inventory_custody_roots c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) OR EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody protected original quality/current source');END;
CREATE TRIGGER inventory_custody_quality_event_time BEFORE INSERT ON inventory_custody_events WHEN EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody original quality chronology');END;
